from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

import heapq
from itertools import combinations


def _route(data, minimum, exact):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    initial_mask = 1 << indexes[data["source"]] if data["source"] in indexes else 0
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = (data["source"], initial_mask, 0)
    distances = {start: data["start"]}
    queue = [(data["start"],) + start]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full and (not exact or used == data["coupons"]):
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                discount = edge.get("discount", 0)
                options.append((max(minimum, edge["duration"] - discount), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                nxt = edge["v"]
                next_mask = mask | (1 << indexes[nxt] if nxt in indexes else 0)
                next_state = (nxt, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    def rounded(n, divisor):
        if data["rounding"] == "half_up":
            return (n + divisor // 2) // divisor
        return n // divisor

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages, reverse=True)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    initial = {name: [(bounds[0], bounds[1])]
               for name, bounds in data["roots"].items()}
    best = None
    best_versions = None

    def cycle(edges):
        active, done = set(), set()
        def visit(name):
            if name in active:
                return True
            if name in done:
                return False
            active.add(name)
            if any(visit(child) for child in edges.get(name, ())):
                return True
            active.remove(name)
            done.add(name)
            return False
        return any(visit(name) for name in edges)

    def search(chosen, constraints, edges):
        nonlocal best, best_versions
        for name, version in chosen.items():
            if any(not low <= version <= high for low, high in constraints.get(name, ())):
                return
        unresolved = [name for name in constraints if name not in chosen]
        if not unresolved:
            if cycle(edges):
                return
            vector = tuple(chosen.get(name, -1) for name in names)
            if best is None or vector < best:
                best, best_versions = vector, dict(chosen)
            return
        name = max(unresolved)
        intervals = constraints[name]
        rows = [row for row in packages.get(name, [])
                if all(low <= row["version"] <= high for low, high in intervals)
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_chosen = dict(chosen)
            next_chosen[name] = version
            next_constraints = {key: list(value) for key, value in constraints.items()}
            next_edges = {key: list(value) for key, value in edges.items()}
            next_edges.setdefault(name, [])
            valid = True
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                child = dep["name"]
                interval = (dep["min"], dep["max"])
                next_constraints.setdefault(child, []).append(interval)
                next_edges[name].append(child)
                if child in next_chosen and not interval[0] <= next_chosen[child] <= interval[1]:
                    valid = False
                    break
            if valid:
                search(next_chosen, next_constraints, next_edges)

    search({}, initial, {})
    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _jobs(data):
    jobs = [job for job in data["jobs"] if job["id"] not in data.get("blocked", [])]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    k = data["k"]
    best_value = None
    best_ids = None
    for subset in combinations(jobs, k):
        ids = sorted(job["id"] for job in subset)
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        if best_value is None or value > best_value or (value == best_value and ids < best_ids):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


SOLVERS = {
    "component_01": lambda data: _route(data, 2, False),
    "component_02": lambda data: _route(data, 2, True),
    "component_03": lambda data: _route(data, 1, False),
    "component_04": lambda data: _route(data, 1, True),
    "component_05": lambda data: _route(data, 2, False),
    "component_06": _ledger,
    "component_07": _dependencies,
    "component_08": _jobs,
}
